// Test for dependency creation (bf-3wfk)
//
// The acceptance criteria states:
// - Use 'bf dep add blocker bead-b --blocks bead-a' to create dependency
// - Verify with 'bf show bead-a' that bead-b is listed as a blocker
// - Verify bead-a status shows as 'blocked'
//
// Note: The current CLI uses 'bf dep add <issue> <depends_on> -t <type>'
// which is simpler than the acceptance criteria format.

#[cfg(test)]
mod dependency_tests {
    use std::path::PathBuf;
    use tempfile::TempDir;

    // Helper to create test workspace
    fn create_test_workspace() -> (TempDir, PathBuf) {
        let temp_dir = TempDir::new().unwrap();
        let workspace_dir = temp_dir.path();
        let beads_dir = workspace_dir.join(".beads");
        std::fs::create_dir_all(&beads_dir).unwrap();

        // Create config
        let config_path = beads_dir.join("config.yaml");
        std::fs::write(
            &config_path,
            r#"issue_prefixes: [bf]
default_priority: 2
default_type: task
claim_ttl_minutes: 30
"#,
        )
        .unwrap();

        // Create metadata
        let metadata_path = beads_dir.join("metadata.json");
        std::fs::write(&metadata_path, r#"{"database": "beads.db", "jsonl_export": "issues.jsonl"}"#)
            .unwrap();

        // Initialize database
        let db_path = beads_dir.join("beads.db");
        let _storage = bead_forge::storage::Storage::open(&db_path).unwrap();

        (temp_dir, beads_dir)
    }

    #[test]
    fn test_dependency_creation_basic() {
        let (_temp_dir, beads_dir) = create_test_workspace();

        // Create two test beads
        let bead_a = create_bead(&beads_dir, "Task A");
        let bead_b = create_bead(&beads_dir, "Task B");

        // Use current CLI format: bf dep add <issue> <depends_on> -t <type>
        // This means: bead-b depends on bead-a (bead-a blocks bead-b)
        let output = std::process::Command::new("cargo")
            .args(["run", "--", "dep", "add", &bead_b, &bead_a, "-t", "blocks"])
            .current_dir(beads_dir.parent().unwrap())
            .env("BF_TEST_WORKSPACE", beads_dir)
            .output()
            .unwrap();

        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);

        println!("stdout: {}", stdout);
        println!("stderr: {}", stderr);

        // Verify the dependency was added
        assert!(output.status.success(), "Command failed: {}", stderr);

        // Verify with bf show
        let output = std::process::Command::new("cargo")
            .args(["run", "--", "show", &bead_b])
            .current_dir(beads_dir.parent().unwrap())
            .env("BF_TEST_WORKSPACE", beads_dir)
            .output()
            .unwrap();

        let stdout = String::from_utf8_lossy(&output.stdout);
        // Check that the bead shows bead-a as a blocker
        assert!(stdout.contains(&bead_a), "bead-a should be listed as a blocker");
    }

    fn create_bead(beads_dir: &PathBuf, title: &str) -> String {
        let output = std::process::Command::new("cargo")
            .args(["run", "--", "create", "--title", title])
            .current_dir(beads_dir.parent().unwrap())
            .env("BF_TEST_WORKSPACE", beads_dir)
            .output()
            .unwrap();

        String::from_utf8_lossy(&output.stdout).trim().to_string()
    }
}
